{
  "name": "APP TẠO ĐỀ TN TIẾNG ANH CT 2018+ LUYỆN TỪ- HÀ THU AI",
  "description": "Ứng dụng tạo đề thi Tốt nghiệp THPT Tiếng Anh theo format 2025/2026 sử dụng Gemini AI.",
  "requestFramePermissions": []
}

import React, { useState } from 'react';
import { generateExamStructure, generateGradingKey } from './services/geminiService';
import { Difficulty, GeneratedExam, GradingResult } from './types';
import { TestDisplay } from './components/TestDisplay';
import { 
  Sparkles, 
  Upload, 
  FileText, 
  CheckCircle2, 
  Loader2,
  BookOpen,
  Settings2,
  ChevronDown,
  Info,
  Crown,
  Trophy,
  Languages
} from 'lucide-react';

const App: React.FC = () => {
  const [context, setContext] = useState<string>('');
  const [level, setLevel] = useState<Difficulty>(Difficulty.B1);
  const [exam, setExam] = useState<GeneratedExam | null>(null);
  const [userAnswers, setUserAnswers] = useState<Record<number, string>>({});
  const [grading, setGrading] = useState<Record<number, GradingResult> | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isGrading, setIsGrading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.type === "text/plain") {
      const reader = new FileReader();
      reader.onload = (event) => setContext(event.target?.result as string || "");
      reader.readAsText(file);
    } else {
      alert("Vui lòng sử dụng file .txt");
    }
  };

  const handleGenerateExam = async () => {
    if (!process.env.API_KEY) {
      setError("Thiếu API Key.");
      return;
    }
    setIsGenerating(true);
    setError(null);
    setExam(null);
    setGrading(null);
    setUserAnswers({});
    try {
      const result = await generateExamStructure(context, level);
      setExam(result);
    } catch (e: any) {
      setError(e.message || "Lỗi khi tạo đề.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGetGrading = async () => {
    if (!exam) return;
    setIsGrading(true);
    try {
      const response = await generateGradingKey(exam);
      const gradingMap: Record<number, GradingResult> = {};
      response.results.forEach(r => gradingMap[r.questionId] = r);
      setGrading(gradingMap);
    } catch (e: any) {
      setError(e.message || "Lỗi khi chấm điểm.");
    } finally {
      setIsGrading(false);
    }
  };

  const handleDownloadWord = () => {
    if (!exam) return;
    const content = `<html><body>${exam.title}...</body></html>`; // Giữ logic cũ
    const blob = new Blob([content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Exam_${Date.now()}.doc`;
    link.click();
  };

  const handleAnswerSelect = (qid: number, ans: string) => {
    setUserAnswers(prev => ({ ...prev, [qid]: ans }));
  };

  const calculateScore = () => {
    if (!exam || !grading) return 0;
    let correct = 0;
    Object.keys(grading).forEach(key => {
      const qid = parseInt(key);
      if (userAnswers[qid] === grading[qid].correctAnswer) correct++;
    });
    return ((correct / 40) * 10).toFixed(2);
  };

  return (
    <div className="min-h-screen flex flex-col bg-navy-950 font-sans selection:bg-gold-400 selection:text-navy-900">

      {/* 1. HEADER */}
      <header className="sticky top-0 bg-navy-900/80 backdrop-blur-xl border-b gold-border h-16 flex items-center justify-between px-8 z-50 premium-shadow">
        <div className="flex items-center gap-4">
          <div className="relative">
             <Trophy className="text-gold-400 w-8 h-8 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]" />
             <div className="absolute -top-1 -right-1">
                <Crown className="w-3 h-3 text-gold-300 animate-bounce" />
             </div>
          </div>
          <h1 className="font-serif font-bold text-lg md:text-xl gold-text-gradient tracking-tight truncate max-w-[200px] md:max-w-none">APP TẠO ĐỀ TN TIẾNG ANH CT 2018+ LUYỆN TỪ- HÀ THU AI</h1>
        </div>

        <div className="flex items-center gap-4 sm:gap-6">
           {/* IMPROVE VOCAB BUTTON */}
           <a 
             href="https://ai.studio/apps/drive/1GJXe4VB2af0bsZAaXWfqbDOzCCcESNyJ?fullscreenApplet=true" 
             target="_blank" 
             rel="noopener noreferrer"
             className="flex items-center gap-2 px-3 py-1.5 bg-blue-500/10 rounded-full border border-blue-400/30 text-blue-400 hover:bg-blue-500/20 transition-all group"
           >
             <Languages size={14} className="group-hover:rotate-12 transition-transform" />
             <span className="text-[10px] uppercase font-black tracking-widest hidden sm:inline">Improve Vocab</span>
             <span className="text-[10px] uppercase font-black tracking-widest sm:hidden">Vocab</span>
           </a>

           {grading && (
             <div className="flex items-center gap-3 px-4 py-1.5 bg-gold-400/10 rounded-full border border-gold-400/30">
               <span className="text-[10px] uppercase font-black text-gold-400 tracking-widest hidden sm:inline">FINAL SCORE:</span>
               <span className="text-lg font-serif font-bold text-gold-200">{calculateScore()}/10</span>
             </div>
           )}
           <div className="text-[10px] text-gold-300 font-black uppercase tracking-[0.2em] bg-white/5 px-4 py-1.5 rounded-full border gold-border hidden lg:block">
              Gemini 2.0 Pro Ready
           </div>
        </div>
      </header>

      {/* 2. PREMIUM CONTROL PANEL */}
      <section className="bg-navy-900 border-b gold-border p-6 md:p-8 relative overflow-hidden">
        {/* Decorative background element */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-gold-600/5 blur-[120px] rounded-full -mr-48 -mt-48"></div>

        <div className="max-w-7xl mx-auto relative z-10">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Input Area */}
            <div className="lg:col-span-6 space-y-3">
              <label className="flex items-center gap-2 text-[10px] font-black text-gold-400 uppercase tracking-[0.2em]">
                <BookOpen size={14} />
                Ngữ liệu / Chủ đề ôn tập
              </label>
              <div className="relative">
                <textarea
                  className="w-full h-32 p-4 text-sm bg-navy-950/50 border gold-border rounded-2xl focus:ring-1 focus:ring-gold-400 focus:border-gold-400 outline-none resize-none transition-all text-slate-200 placeholder:text-slate-600"
                  placeholder="Paste English content or topic here..."
                  value={context}
                  onChange={(e) => setContext(e.target.value)}
                />
                <label className="absolute bottom-3 right-3 cursor-pointer bg-gold-400 hover:bg-gold-300 text-navy-900 text-[10px] font-black py-1.5 px-3 rounded-lg flex items-center gap-1.5 shadow-lg transition-all active:scale-95">
                  <Upload size={12} />
                  <span>UPLOAD .TXT</span>
                  <input type="file" accept=".txt" onChange={handleFileUpload} className="hidden" />
                </label>
              </div>
            </div>

            {/* Controls */}
            <div className="lg:col-span-6 grid grid-cols-1 sm:grid-cols-2 gap-6">
               <div className="space-y-3">
                  <label className="flex items-center gap-2 text-[10px] font-black text-gold-400 uppercase tracking-[0.2em]">
                    <Settings2 size={14} />
                    Trình độ học thuật
                  </label>
                  <div className="relative">
                    <select
                      value={level}
                      onChange={(e) => setLevel(e.target.value as Difficulty)}
                      className="w-full appearance-none p-4 bg-navy-950/50 border gold-border rounded-2xl text-sm font-bold focus:ring-1 focus:ring-gold-400 outline-none pr-12 text-gold-100 cursor-pointer hover:bg-navy-800 transition-colors"
                    >
                      {Object.values(Difficulty).map(d => (
                        <option key={d} value={d} className="bg-navy-900">{d}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gold-400 pointer-events-none" size={18} />
                  </div>
               </div>

               <div className="flex flex-col justify-end">
                  <button
                    onClick={handleGenerateExam}
                    disabled={isGenerating}
                    className="w-full py-4 gold-gradient text-navy-950 rounded-2xl font-black shadow-[0_0_20px_rgba(251,191,36,0.3)] hover:shadow-[0_0_30px_rgba(251,191,36,0.5)] transition-all flex items-center justify-center gap-3 disabled:opacity-50 text-sm uppercase tracking-widest active:scale-95"
                  >
                    {isGenerating ? <Loader2 className="animate-spin w-5 h-5" /> : <Sparkles className="w-5 h-5" />}
                    {isGenerating ? 'Drafting...' : 'Tạo đề thi ngay'}
                  </button>
               </div>

               {exam && (
                  <div className="sm:col-span-2 flex items-center gap-4 animate-in fade-in slide-in-from-top-4">
                    <button
                      onClick={handleDownloadWord}
                      className="flex-1 py-3.5 bg-transparent border-2 border-gold-400/50 hover:border-gold-400 text-gold-400 rounded-2xl font-black text-xs transition-all flex items-center justify-center gap-2.5 uppercase tracking-widest hover:bg-gold-400/5"
                    >
                      <FileText className="w-4 h-4" />
                      Xuất File Word
                    </button>

                    <div className="flex-[1.5] relative group">
                      <div className="absolute -inset-0.5 bg-gold-400 rounded-2xl blur opacity-30 group-hover:opacity-60 transition duration-1000 group-hover:duration-200"></div>
                      <button
                        onClick={handleGetGrading}
                        disabled={isGrading}
                        className={`relative w-full py-3.5 rounded-2xl font-black text-xs flex items-center justify-center gap-2.5 transition-all uppercase tracking-widest shadow-xl border border-gold-400/20 ${grading ? 'bg-gold-100 text-navy-900' : 'bg-navy-950 text-gold-400 hover:bg-gold-400 hover:text-navy-950'}`}
                      >
                        {isGrading ? <Loader2 className="animate-spin w-4 h-4" /> : <CheckCircle2 className="w-4 h-4" />}
                        {isGrading ? 'AI đang chấm...' : (grading ? 'Xem lời giải' : 'Nộp bài & Chấm điểm')}
                      </button>
                    </div>
                  </div>
               )}
            </div>
          </div>
        </div>
      </section>

      {/* 3. EXAM CONTENT */}
      <main className="flex-1 overflow-y-auto p-4 md:p-12 relative">
        <div className="max-w-6xl mx-auto">
          {error && (
            <div className="mb-8 bg-red-950/40 text-red-400 p-4 rounded-2xl border border-red-800 shadow-2xl flex items-center justify-between animate-in zoom-in-95">
              <div className="flex items-center gap-3">
                <Info size={18} />
                <span className="font-bold text-sm tracking-wide">{error}</span>
              </div>
              <button onClick={() => setError(null)} className="text-[10px] font-black uppercase tracking-widest hover:text-red-300">Close</button>
            </div>
          )}

          {!exam ? (
            <div className="h-[50vh] flex flex-col items-center justify-center bg-navy-900/40 rounded-[3rem] border border-dashed border-gold-400/20 premium-shadow">
              <div className="w-24 h-24 bg-navy-800 rounded-full flex items-center justify-center mb-8 border gold-border shadow-inner">
                <BookOpen className="w-10 h-10 text-gold-400/30" />
              </div>
              <h3 className="text-2xl font-serif font-bold gold-text-gradient mb-3">Sẵn sàng khởi tạo học thuật</h3>
              <p className="max-w-md text-center text-slate-500 text-sm leading-relaxed px-6">
                Nhập chủ đề hoặc nội dung cần ôn luyện. Trí tuệ nhân tạo sẽ thiết kế bộ đề 40 câu theo đúng chuẩn cấu trúc thi Tốt nghiệp 2026.
              </p>
            </div>
          ) : (
            <div className="bg-white text-navy-950 shadow-[0_30px_100px_rgba(0,0,0,0.6)] p-8 md:p-20 rounded-[2.5rem] relative animate-in fade-in slide-in-from-bottom-8 duration-700">
               {/* Paper Decoration */}
               <div className="flex flex-col items-center mb-16 text-center">
                  <div className="mb-6 opacity-20">
                     <Trophy size={48} className="text-navy-900" />
                  </div>
                  <div className="space-y-2">
                    <p className="text-[11px] font-black text-slate-500 uppercase tracking-[0.3em]">CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</p>
                    <p className="text-sm font-bold text-navy-900 border-b-2 border-navy-900 inline-block pb-1">Độc lập - Tự do - Hạnh phúc</p>
                  </div>
                  <div className="mt-8 space-y-1">
                    <p className="text-lg font-serif font-black text-navy-900 uppercase tracking-tight">Kỳ thi tốt nghiệp THPT năm 2026</p>
                    <p className="text-xs font-bold text-slate-500">Bài thi: NGOẠI NGỮ — Môn thi: TIẾNG ANH</p>
                  </div>
               </div>

               <TestDisplay 
                 exam={exam} 
                 grading={grading} 
                 userAnswers={userAnswers} 
                 onAnswerSelect={handleAnswerSelect} 
               />

               <div className="mt-20 pt-10 border-t-2 border-dashed border-slate-200 text-center text-slate-300 font-serif italic">
                 --- HẾT ---
               </div>
            </div>
          )}
        </div>
      </main>

      {/* Loading Overlay */}
      {isGenerating && (
        <div className="fixed inset-0 bg-navy-950/90 backdrop-blur-xl z-[100] flex flex-col items-center justify-center">
          <div className="relative flex flex-col items-center p-12 bg-navy-900 rounded-[3rem] border gold-border premium-shadow">
            <div className="relative mb-8">
              <Loader2 className="w-20 h-20 text-gold-400 animate-spin" />
              <div className="absolute inset-0 flex items-center justify-center">
                 <Crown className="w-8 h-8 text-gold-300 animate-pulse" />
              </div>
            </div>
            <h3 className="text-3xl font-serif font-black gold-text-gradient mb-4">Drafting Excellence</h3>
            <p className="text-slate-400 text-sm max-w-xs text-center leading-relaxed">
              Trí tuệ nhân tạo đang phân tích dữ liệu và thiết kế cấu trúc đề thi 40 câu hỏi. Đang tinh chỉnh độ khó và tính học thuật...
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
